 65	 * 주문 배송 상태를 조회하고 처리합니다.
 66	 */
 67	@Slf4j
 68	public class ShipmentItemProcessor implements ItemProcessor<OrderShipment, OrderShipment> {
 69	
 70	    private final PlaywrightBrowserManager browserManager;
 71	    private final NotificationCommandService notificationService;
 72	    private final OrderShipmentCommandService orderService;
 73	
 74	    private static final String TRACKING_URL_PREFIX = "https://trace.cjlogistics.com/next/tracking.html?wblNo=";
 75	    private static final String STATUS_SELECTOR = "tbody#statusDetail tr";
 76	    private static final int TIMEOUT_MS = 30000; // 30초
 77	
 78	    /**
 79	     * 배송 상태 처리기 생성자
 80	     *
 81	     * @param browserManager Playwright 브라우저 관리자
 82	     * @param notificationService 알림 서비스
 83	     * @param orderService 주문 서비스
 84	     */
 85	    public ShipmentItemProcessor(
 86	            PlaywrightBrowserManager browserManager,
 87	            NotificationCommandService notificationService,
 88	            OrderShipmentCommandService orderService
 89	    ) {
 90	        this.browserManager = browserManager;
 91	        this.notificationService = notificationService;
 92	        this.orderService = orderService;
 93	    }
 94	
 95	    /**
 96	     * 주문 배송의 상태를 외부 서비스를 통해 조회하고 업데이트합니다.
 97	     *
 98	     * @param orderShipment 처리할 배송 정보
 99	     * @return 업데이트된 배송 정보
100	     * @throws Exception 처리 중 오류 발생 시
101	     */
102	    @Override
103	    public OrderShipment process(OrderShipment orderShipment) throws Exception {
104	        String trackingNumber = orderShipment.getTrackingNumber();
105	        Long shipmentId = orderShipment.getId();
106	
107	        if (trackingNumber == null || trackingNumber.isBlank()) {
108	            log.warn("유효하지 않은 운송장 번호: shipmentId={}", shipmentId);
109	            throw new ShipmentException(ShipmentErrorCode.TRACKING_NUMBER_INVALID);
110	        }
111	
112	        log.info("배송 상태 처리 시작: shipmentId={}, trackingNumber={}, currentStatus={}",
113	                shipmentId, trackingNumber, orderShipment.getStatus());
114	
115	        Page page = null;
116	        try {
117	            // browserManager를 통해 페이지 생성
118	            page = browserManager.newPage();
119	            if (page == null) {
120	                throw new ShipmentException(ShipmentErrorCode.BROWSER_INITIALIZATION_ERROR);
121	            }
122	
123	            // 타임아웃 설정
124	            page.setDefaultTimeout(TIMEOUT_MS);
125	
126	            // 배송 추적 URL로 이동
127	            String url = TRACKING_URL_PREFIX + trackingNumber;
128	            log.debug("배송 조회 페이지로 이동: {}", url);
129	            page.navigate(url);
130	
131	            // 배송 상태 테이블 로드 대기
132	            log.debug("배송 상태 테이블 로드 대기");
133	            page.waitForSelector(STATUS_SELECTOR);
134	
135	            // 최종 HTML 가져오기
136	            String renderedHtml = page.content();
137	            log.debug("페이지 HTML 로드 완료 (길이: {})", renderedHtml.length());
138	
139	            // HTML 파싱하여 배송 상태 추출
140	            String statusText = parseStatusFromHtml(renderedHtml, trackingNumber);
141	            ShipmentStatus newStatus = mapToShipmentStatus(statusText);
142	
143	            log.debug("배송 상태 조회 결과: shipmentId={}, statusText={}, mappedStatus={}",
144	                    shipmentId, statusText, newStatus);
145	
146	            // 현재 상태와 동일한 경우 중복 처리 방지
147	            if (orderShipment.getStatus() == newStatus) {
148	                log.debug("상태 변경 없음 (중복 처리 방지): shipmentId={}, status={}",
149	                        shipmentId, newStatus);
150	                return orderShipment;
151	            }
152	
153	            // 상태에 따른 처리
154	            if (newStatus == ShipmentStatus.DELIVERED) {
155	                log.info("배송 완료 처리: shipmentId={}, orderId={}",
156	                        shipmentId, orderShipment.getOrder().getId());
157	
158	                // 배송 상태 업데이트
159	                orderShipment.updateStatus(ShipmentStatus.DELIVERED);
160	
161	                // 주문 완료 처리 및 알림
162	                orderService.completeOrder(orderShipment.getOrder().getId());
163	                notificationService.notifyShipmentCompleted(orderShipment.getOrder());
164	
165	            } else if (newStatus == ShipmentStatus.OUT_FOR_DELIVERY) {
166	                log.info("배송 출발 처리: shipmentId={}", shipmentId);
167	                orderShipment.updateStatus(ShipmentStatus.OUT_FOR_DELIVERY);
168	
169	            } else {
170	                log.info("배송 중 상태 업데이트: shipmentId={}", shipmentId);
171	                orderShipment.updateStatus(ShipmentStatus.IN_TRANSIT);
172	            }
173	
174	            log.info("배송 상태 처리 완료: shipmentId={}, newStatus={}",
175	                    shipmentId, orderShipment.getStatus());
176	
177	            return orderShipment;
178	
179	        } catch (Exception e) {
180	            log.error("배송 상태 처리 중 오류 발생: shipmentId={}, trackingNumber={}, error={}",
181	                    shipmentId, trackingNumber, e.getMessage(), e);
182	
183	            // ShipmentException 타입이 아닌 경우 래핑
184	            if (!(e instanceof ShipmentException)) {
185	                throw new ShipmentException(
186	                        ShipmentErrorCode.EXTERNAL_TRACKING_SERVICE_ERROR,
187	                        "배송 상태 조회 중 오류 발생: " + e.getMessage(),
188	                        e
189	                );
190	            }
191	            throw e;
192	        } finally {
193	            // 페이지 리소스 해제
194	            if (page != null) {
195	                try {
196	                    page.close();
197	                    log.debug("페이지 리소스 해제 완료");
198	                } catch (Exception e) {
199	                    log.warn("페이지 닫기 실패: {}", e.getMessage());
200	                }
201	            }
202	        }
203	    }
204	
205	    /**
206	     * HTML에서 배송 상태를 파싱합니다.
207	     *
208	     * @param html 파싱할 HTML 문자열
209	     * @param trackingNumber 로깅용 운송장 번호
210	     * @return 배송 상태 문자열
211	     * @throws ShipmentException 파싱 실패 시 발생
212	     */
213	    private String parseStatusFromHtml(String html, String trackingNumber) {
214	        try {
215	            Document doc = Jsoup.parse(html);
216	            Elements rows = doc.select(STATUS_SELECTOR);
217	
218	            if (rows.isEmpty()) {
219	                log.warn("배송 상태 테이블이 비어 있음: 운송장={}", trackingNumber);
220	                throw new ShipmentException(
221	                        ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
222	                        "배송 정보가 없습니다. 운송장 번호를 확인해주세요: " + trackingNumber
223	                );
224	            }
225	
226	            // 마지막 행(최신 상태)의 5번째 컬럼 선택
227	            String statusText = rows.last().select("td").get(4).text().trim();
228	
229	            if (statusText.isEmpty()) {
230	                log.warn("배송 상태 텍스트가 비어 있음: 운송장={}", trackingNumber);
231	                throw new ShipmentException(
232	                        ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
233	                        "배송 상태 정보를 찾을 수 없습니다."
234	                );
235	            }
236	
237	            return statusText;
238	
239	        } catch (IndexOutOfBoundsException e) {
240	            log.error("HTML 파싱 중 인덱스 오류: 운송장={}, 오류={}", trackingNumber, e.getMessage(), e);
241	            throw new ShipmentException(
242	                    ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
243	                    "배송 상태 정보 파싱 실패: 예상한 형식과 다릅니다.",
244	                    e
245	            );
246	        } catch (Exception e) {
247	            if (e instanceof ShipmentException) {
248	                throw (ShipmentException) e;
249	            }
250	
251	            log.error("HTML 파싱 중 오류 발생: 운송장={}, 오류={}", trackingNumber, e.getMessage(), e);
252	            throw new ShipmentException(
253	                    ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
254	                    "배송 상태 정보 파싱 실패: " + e.getMessage(),
255	                    e
256	            );
257	        }
258	    }
259	
260	    /**
261	     * 배송사 상태 텍스트를 내부 ShipmentStatus로 매핑합니다.
262	     *
263	     * @param statusText 배송사 상태 텍스트
264	     * @return 매핑된 ShipmentStatus
265	     */
266	    private ShipmentStatus mapToShipmentStatus(String statusText) {
267	        return switch (statusText) {
268	            case "배송완료" -> ShipmentStatus.DELIVERED;
269	            case "배송출발" -> ShipmentStatus.OUT_FOR_DELIVERY;
270	            default -> ShipmentStatus.IN_TRANSIT;
271	        };
272	    }
273	}package com.fream.back.domain.shipment.config;
274	
275	import com.fream.back.domain.notification.service.command.NotificationCommandService;
276	import com.fream.back.domain.shipment.entity.OrderShipment;
277	import com.fream.back.domain.shipment.entity.ShipmentStatus;
278	import com.fream.back.domain.shipment.exception.ShipmentErrorCode;
279	import com.fream.back.domain.shipment.exception.ShipmentException;
280	import com.fream.back.domain.shipment.repository.OrderShipmentRepository;
281	import com.fream.back.domain.shipment.service.command.OrderShipmentCommandService;
282	import com.fream.back.global.utils.CjTrackingPlaywright;
283	import com.fream.back.global.utils.PlaywrightBrowserManager;
284	import jakarta.persistence.EntityManagerFactory;
285	import lombok.RequiredArgsConstructor;
286	import lombok.extern.slf4j.Slf4j;
