305	
306	/**
307	 * 배송 상태 자동 업데이트를 위한 배치 작업 구성
308	 */
309	@Slf4j
310	@Configuration
311	@RequiredArgsConstructor
312	public class UpdateShipmentStatusesJobConfig {
313	
314	    private final JobRepository jobRepository;
315	    private final PlatformTransactionManager transactionManager;
316	    private final EntityManagerFactory entityManagerFactory;
317	
318	    private final OrderShipmentRepository orderShipmentRepository;
319	    private final NotificationCommandService notificationService;
320	    private final OrderShipmentCommandService orderService;
321	    private final CjTrackingPlaywright cjTrackingPlaywright;
322	
323	    private static final int CHUNK_SIZE = 50;
324	    private static final int SKIP_LIMIT = 50;
325	
326	    @Bean
327	    public Job updateShipmentStatusesJob() {
328	        log.info("배송 상태 업데이트 작업 구성");
329	        return new JobBuilder("updateShipmentStatusesJob", jobRepository)
330	                .start(updateShipmentStatusesStep())
331	                .build();
332	    }
333	
334	    @Bean
335	    public Step updateShipmentStatusesStep() {
336	        log.info("배송 상태 업데이트 스텝 구성: 청크 크기={}, 스킵 제한={}", CHUNK_SIZE, SKIP_LIMIT);
337	
338	        return new StepBuilder("updateShipmentStatusesStep", jobRepository)
339	                .<OrderShipment, OrderShipment>chunk(CHUNK_SIZE, transactionManager)
340	                .reader(shipmentItemReader())
341	                .processor(new ShipmentItemProcessor(
342	                        playwrightBrowserManager(), // Bean or new
343	                        notificationService,
344	                        orderService
345	                ))
346	                .writer(shipmentJpaItemWriter())
347	                .faultTolerant()
348	                .skip(Exception.class)
349	                .skipLimit(SKIP_LIMIT)
350	                .listener(shipmentSkipListener())
351	                // ★ Step Execution Listener로 Browser 관리 리스너 추가
352	                .listener(new BrowserManageStepListener(playwrightBrowserManager()))
353	                .build();
354	    }
355	
356	    /**
357	     * 1) Reader: 상태가 IN_TRANSIT 또는 OUT_FOR_DELIVERY 인 OrderShipment 목록을 페이지 단위로 읽음
358	     */
359	    @Bean
360	    @StepScope
361	    public JpaPagingItemReader<OrderShipment> shipmentItemReader() {
362	        log.debug("배송 상태 업데이트 ItemReader 구성");
363	        return new JpaPagingItemReaderBuilder<OrderShipment>()
364	                .name("shipmentItemReader")
365	                .entityManagerFactory(entityManagerFactory)
366	                .pageSize(CHUNK_SIZE)
367	                .queryString("SELECT s FROM OrderShipment s WHERE s.status IN ('IN_TRANSIT','OUT_FOR_DELIVERY') AND s.trackingNumber IS NOT NULL")
368	                .build();
369	    }
370	
371	    /**
372	     * 2) Processor: 각 OrderShipment에 대해 CJ대한통운 페이지를 조회하여 상태 갱신
373	     *    - parseCjLogisticsStatus(...) 를 통해 배송 상태 파싱
374	     *    - DELIVERY 완료 시 알림, Order 상태 완료 등도 여기서 처리 가능
375	     */
376	    @Bean
377	    @StepScope
378	    public ItemProcessor<OrderShipment, OrderShipment> shipmentItemProcessor() {
379	        log.debug("배송 상태 업데이트 ItemProcessor 구성");
380	
381	        // 만약 Processor를 여러 단계로 나누고 싶다면 CompositeItemProcessorBuilder 사용도 가능
382	        return orderShipment -> {
383	            String trackingNumber = orderShipment.getTrackingNumber();
384	            Long shipmentId = orderShipment.getId();
385	
386	            if (trackingNumber == null || trackingNumber.isBlank()) {
387	                log.warn("유효하지 않은 운송장 번호: shipmentId={}", shipmentId);
388	                throw new ShipmentException(ShipmentErrorCode.TRACKING_NUMBER_INVALID);
389	            }
390	
391	            log.info("배송 상태 조회 시작: shipmentId={}, trackingNumber={}, currentStatus={}",
392	                    shipmentId, trackingNumber, orderShipment.getStatus());
393	
394	            try {
395	                // 2-1) 현재 상태 가져오기
396	                String currentStatus = cjTrackingPlaywright.getCurrentTrackingStatus(trackingNumber);
397	                log.debug("배송 상태 조회 결과: shipmentId={}, currentStatus={}", shipmentId, currentStatus);
398	
399	                // 2-2) 매핑
400	                ShipmentStatus newStatus = mapToShipmentStatus(currentStatus);
401	                log.debug("배송 상태 매핑 결과: currentStatus={}, mappedStatus={}", currentStatus, newStatus);
402	
403	                // 현재 상태와 동일한 경우 중복 처리 방지
404	                if (orderShipment.getStatus() == newStatus) {
405	                    log.debug("상태 변경 없음 (중복 처리 방지): shipmentId={}, status={}",
406	                            shipmentId, newStatus);
407	                    return orderShipment;
408	                }
409	
410	                // 2-3) 상태에 따른 처리
411	                if (newStatus == ShipmentStatus.DELIVERED) {
412	                    log.info("배송 완료 처리: shipmentId={}, orderId={}",
413	                            shipmentId, orderShipment.getOrder().getId());
414	
415	                    orderShipment.updateStatus(ShipmentStatus.DELIVERED);
416	                    // Order 상태도 COMPLETED 로 변경
417	                    orderService.completeOrder(orderShipment.getOrder().getId());
418	                    // 알림 발송
419	                    notificationService.notifyShipmentCompleted(orderShipment.getOrder());
420	                }
421	                else if (newStatus == ShipmentStatus.OUT_FOR_DELIVERY) {
422	                    log.info("배송 출발 처리: shipmentId={}", shipmentId);
423	                    orderShipment.updateStatus(ShipmentStatus.OUT_FOR_DELIVERY);
424	                    // 필요시 알림, 로직 추가
425	                }
426	                else {
427	                    log.info("배송 중 상태 업데이트: shipmentId={}", shipmentId);
428	                    orderShipment.updateStatus(ShipmentStatus.IN_TRANSIT);
429	                }
430	
431	                log.info("배송 상태 처리 완료: shipmentId={}, newStatus={}", shipmentId, orderShipment.getStatus());
432	                return orderShipment; // Writer로 넘김
433	
434	            } catch (Exception e) {
435	                log.error("배송 상태 처리 중 오류 발생: shipmentId={}, trackingNumber={}, error={}",
436	                        shipmentId, trackingNumber, e.getMessage(), e);
437	
438	                // ShipmentException 타입이 아닌 경우 래핑
439	                if (!(e instanceof ShipmentException)) {
440	                    throw new ShipmentException(
441	                            ShipmentErrorCode.EXTERNAL_TRACKING_SERVICE_ERROR,
442	                            "배송 상태 조회 중 오류 발생: " + e.getMessage(),
443	                            e
444	                    );
445	                }
446	                throw e;
447	            }
448	        };
449	    }
450	
451	    /**
452	     * CJ대한통운 배송 상태 조회를 위한 메서드
453	     *
454	     * @param trackingNumber 운송장 번호
455	     * @return 배송 상태 텍스트
456	     * @throws Exception 조회 실패 시 발생
457	     */
458	    private String parseCjLogisticsStatus(String trackingNumber) throws Exception {
459	        log.debug("운송장 조회 시작 (Jsoup): trackingNumber={}", trackingNumber);
460	
461	        try {
462	            // 예시: 로직 단순화
463	            String url = "https://trace.cjlogistics.com/next/tracking.html?wblNo=" + trackingNumber;
464	            Document doc = Jsoup.connect(url).get();
465	            // tbody#statusDetail 의 마지막 tr => 5번째 td
466	            Elements rows = doc.select("tbody#statusDetail tr");
467	            if (rows.isEmpty()) {
468	                log.warn("배송 정보가 없음: trackingNumber={}", trackingNumber);
469	                throw new ShipmentException(
470	                        ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
471	                        "배송 정보가 없습니다. trackingNo=" + trackingNumber
472	                );
473	            }
474	
475	            String status = rows.last().select("td").get(4).text();
476	            log.debug("운송장 조회 완료: trackingNumber={}, status={}", trackingNumber, status);
477	            return status;
478	
479	        } catch (Exception e) {
480	            log.error("운송장 조회 실패: trackingNumber={}, error={}", trackingNumber, e.getMessage(), e);
481	
482	            if (e instanceof ShipmentException) {
483	                throw e;
484	            }
485	
486	            throw new ShipmentException(
487	                    ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
488	                    "배송 정보 조회 중 오류 발생: " + e.getMessage(),
489	                    e
490	            );
491	        }
492	    }
493	
494	    /**
495	     * 배송사 상태 텍스트를 내부 ShipmentStatus로 매핑합니다.
496	     *
497	     * @param statusText 배송사 상태 텍스트
498	     * @return 매핑된 ShipmentStatus
499	     */
500	    private ShipmentStatus mapToShipmentStatus(String statusText) {
501	        return switch (statusText) {
502	            case "배송완료" -> ShipmentStatus.DELIVERED;
503	            case "배송출발" -> ShipmentStatus.OUT_FOR_DELIVERY;
504	            default -> ShipmentStatus.IN_TRANSIT;
505	        };
506	    }
507	
508	    /**
509	     * 3) Writer: DB에 반영 (상태 갱신)
510	     */
511	    @Bean
512	    @StepScope
513	    public JpaItemWriter<OrderShipment> shipmentJpaItemWriter() {
514	        log.debug("배송 상태 업데이트 ItemWriter 구성");
515	        JpaItemWriter<OrderShipment> writer = new JpaItemWriter<>();
516	        writer.setEntityManagerFactory(entityManagerFactory);
517	        return writer;
518	    }
519	
520	    /**
521	     * SkipListener: 예외 발생 시 로그
522	     */
523	    @Bean
524	    public SkipListener<OrderShipment, OrderShipment> shipmentSkipListener() {
525	        return new SkipListener<>() {
526	            @Override
