305	
306	/**
307	 * 배송 상태 자동 업데이트를 위한 배치 작업 구성
308	 */
309	@Slf4j
310	@Configuration
311	@RequiredArgsConstructor
312	public class UpdateShipmentStatusesJobConfig {
313	
314	    private final JobRepository jobRepository;
315	    private final PlatformTransactionManager transactionManager;
316	    private final EntityManagerFactory entityManagerFactory;
317	
318	    private final OrderShipmentRepository orderShipmentRepository;
319	    private final NotificationCommandService notificationService;
320	    private final OrderShipmentCommandService orderService;
321	    private final CjTrackingPlaywright cjTrackingPlaywright;
322	
323	    private static final int CHUNK_SIZE = 50;
324	    private static final int SKIP_LIMIT = 50;
325	
326	    @Bean
327	    public Job updateShipmentStatusesJob() {
328	        log.info("배송 상태 업데이트 작업 구성");
329	        return new JobBuilder("updateShipmentStatusesJob", jobRepository)
330	                .start(updateShipmentStatusesStep())
331	                .build();
332	    }
333	
334	    @Bean
335	    public Step updateShipmentStatusesStep() {
336	        log.info("배송 상태 업데이트 스텝 구성: 청크 크기={}, 스킵 제한={}", CHUNK_SIZE, SKIP_LIMIT);
337	
338	        return new StepBuilder("updateShipmentStatusesStep", jobRepository)
339	                .<OrderShipment, OrderShipment>chunk(CHUNK_SIZE, transactionManager)
340	                .reader(shipmentItemReader())
341	                .processor(new ShipmentItemProcessor(
342	                        playwrightBrowserManager(), // Bean or new
343	                        notificationService,
344	                        orderService
345	                ))
346	                .writer(shipmentJpaItemWriter())
347	                .faultTolerant()
348	                .skip(Exception.class)
349	                .skipLimit(SKIP_LIMIT)
350	                .listener(shipmentSkipListener())
351	                // ★ Step Execution Listener로 Browser 관리 리스너 추가
352	                .listener(new BrowserManageStepListener(playwrightBrowserManager()))
353	                .build();
354	    }
