451	    /**
452	     * CJ대한통운 배송 상태 조회를 위한 메서드
453	     *
454	     * @param trackingNumber 운송장 번호
455	     * @return 배송 상태 텍스트
456	     * @throws Exception 조회 실패 시 발생
457	     */
458	    private String parseCjLogisticsStatus(String trackingNumber) throws Exception {
459	        log.debug("운송장 조회 시작 (Jsoup): trackingNumber={}", trackingNumber);
460	
461	        try {
462	            // 예시: 로직 단순화
463	            String url = "https://trace.cjlogistics.com/next/tracking.html?wblNo=" + trackingNumber;
464	            Document doc = Jsoup.connect(url).get();
465	            // tbody#statusDetail 의 마지막 tr => 5번째 td
466	            Elements rows = doc.select("tbody#statusDetail tr");
467	            if (rows.isEmpty()) {
468	                log.warn("배송 정보가 없음: trackingNumber={}", trackingNumber);
469	                throw new ShipmentException(
470	                        ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
471	                        "배송 정보가 없습니다. trackingNo=" + trackingNumber
472	                );
473	            }
474	
475	            String status = rows.last().select("td").get(4).text();
476	            log.debug("운송장 조회 완료: trackingNumber={}, status={}", trackingNumber, status);
477	            return status;
478	
479	        } catch (Exception e) {
480	            log.error("운송장 조회 실패: trackingNumber={}, error={}", trackingNumber, e.getMessage(), e);
481	
482	            if (e instanceof ShipmentException) {
483	                throw e;
484	            }
485	
486	            throw new ShipmentException(
487	                    ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
488	                    "배송 정보 조회 중 오류 발생: " + e.getMessage(),
489	                    e
490	            );
491	        }
492	    }
