500	    private ShipmentStatus mapToShipmentStatus(String statusText) {
501	        return switch (statusText) {
502	            case "배송완료" -> ShipmentStatus.DELIVERED;
503	            case "배송출발" -> ShipmentStatus.OUT_FOR_DELIVERY;
504	            default -> ShipmentStatus.IN_TRANSIT;
505	        };
